import { describe, it, expect } from 'vitest'
import { buildStatementPdf, statementPdfFilename, sanitizeFilenamePart, type StatementPdfConfig } from './statementPdf'
import { COMPANY_INFO } from './companyInfo'

/**
 * jsPDF's default (non-embedded) Helvetica font writes text as literal
 * `(...) Tj` string operators in the page content stream — and buildStatementPdf
 * constructs the doc with `compress: false`, so those streams are never
 * Flate-encoded. That means the real generated bytes are inspectable exactly
 * like excelExport.test.ts round-trips a real .xlsx buffer, instead of only
 * asserting against the in-memory config object.
 */
async function extractPdfText(docPromise: ReturnType<typeof buildStatementPdf>): Promise<string> {
  const doc = await docPromise
  const raw = Buffer.from(doc.output('arraybuffer')).toString('latin1')
  // Restrict to BT...ET (text-object) blocks — the embedded logo's raw image
  // bytes live in a separate image XObject stream and can otherwise contain
  // stray '(' / ')' bytes that get misread as text by the naive regex below.
  const textBlocks = raw.match(/BT([\s\S]*?)ET/g) ?? []
  const matches = textBlocks.join(' ').match(/\(((?:[^()\\]|\\.)*)\)/g) ?? []
  return matches
    .map((m) => m.slice(1, -1).replace(/\\([()\\])/g, '$1'))
    .join(' ')
}

function baseConfig(overrides: Partial<StatementPdfConfig> = {}): StatementPdfConfig {
  return {
    client: { name: 'GLOBAL CONSTRUCTION GROUP SAL', address: null, phone: '+961 3 111 222', currency: 'USD' },
    from: '2026-07-04T00:00:00.000Z',
    to: '2026-08-19T00:00:00.000Z',
    rows: [
      { ref: 'SI-1953', rawDate: '2026-07-04T00:00:00.000Z', desc: 'Sales Invoice', debit: 9440.55, credit: 0, balance: 9440.55 },
      { ref: 'RV-543', rawDate: '2026-07-06T00:00:00.000Z', desc: 'CASH RECEIPT FROM GLOBAL CONSTRUCTION GROUP', debit: 0, credit: 5000, balance: 4440.55 },
    ],
    openingBalance: 0,
    periodDebitTotal: 9440.55,
    periodCreditTotal: 5000,
    closingBalance: 4440.55,
    ...overrides,
  }
}

describe('sanitizeFilenamePart / statementPdfFilename', () => {
  it('leaves a normal client name untouched', () => {
    expect(sanitizeFilenamePart('Global Construction Group SAL')).toBe('Global Construction Group SAL')
  })

  it('strips filesystem-illegal characters', () => {
    expect(sanitizeFilenamePart('Al Nakheel / Restaurant: "Main" <Branch>')).toBe('Al Nakheel  Restaurant Main Branch')
  })

  it('builds the exact required filename pattern with no ids/timestamps', () => {
    expect(statementPdfFilename('GLOBAL CONSTRUCTION GROUP SAL')).toBe('GLOBAL CONSTRUCTION GROUP SAL_Statement of Account.pdf')
  })

  it('falls back to a safe default for an all-illegal-character name', () => {
    expect(statementPdfFilename('///')).toBe('Client_Statement of Account.pdf')
  })
})

describe('buildStatementPdf — content', () => {
  it('includes the client name from the provided config, not a hardcoded sample value', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig()))
    expect(text).toContain('GLOBAL CONSTRUCTION GROUP SAL')
  })

  it('includes our company identity (name, address, phone) as the issuer', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig()))
    expect(text).toContain(COMPANY_INFO.name)
    expect(text).toContain(COMPANY_INFO.address)
    expect(text).toContain(COMPANY_INFO.phone)
  })

  it('includes the statement title and the client currency — not an assumed USD', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig({ client: { name: 'Client X', address: null, phone: null, currency: 'LBP' } })))
    expect(text).toContain('STATEMENT OF ACCOUNT')
    expect(text).toContain('LBP')
    // LBP has no standard ASCII symbol, so it falls back to its currency
    // code — balances must never carry a hardcoded "$" for a non-USD statement.
    expect(text).not.toContain('$')
  })

  it('uses the correct currency symbol for USD and EUR, and falls back to the plain code otherwise', async () => {
    const usdText = await extractPdfText(buildStatementPdf(baseConfig({ closingBalance: 2027.97 })))
    expect(usdText).toContain('$2,027.97')

    // The € glyph is WinAnsiEncoding code point 0x80 — this test's crude
    // latin1-based extraction (see extractPdfText's doc comment) doesn't
    // round-trip it correctly, the same limitation already noted for the
    // em-dash elsewhere in this file. Real rendering was confirmed visually:
    // a generated EUR statement shows "€0.00" / "€9,440.55" / "€4,440.55"
    // correctly in an actual PDF viewer. Assert the surrounding digits and
    // that no "$" leaks into a non-USD statement instead.
    const eurText = await extractPdfText(buildStatementPdf(baseConfig({
      client: { name: 'Client X', address: null, phone: null, currency: 'EUR' },
      closingBalance: 2027.97,
    })))
    expect(eurText).toContain('2,027.97')
    expect(eurText).not.toContain('$')

    const lbpText = await extractPdfText(buildStatementPdf(baseConfig({
      client: { name: 'Client X', address: null, phone: null, currency: 'LBP' },
      closingBalance: 2027.97,
    })))
    expect(lbpText).toContain('LBP 2,027.97')
  })

  it('shows the selected From date, human-readable, not today\'s date', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig({ from: '2026-07-04T00:00:00.000Z' })))
    expect(text).toContain('04 Jul 2026')
  })

  it('shows the selected To date, human-readable, not today\'s date', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig({ to: '2026-08-19T00:00:00.000Z' })))
    expect(text).toContain('19 Aug 2026')
  })

  it('never fabricates a date when a bound is genuinely absent (no real-looking date leaks in)', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig({ from: null, to: null })))
    expect(text).toContain('Statement Period:')
    // A real date would read like "Statement Period: 04 Jul ..." — with both
    // bounds null there must be no digit directly after the label.
    expect(text).not.toMatch(/Statement Period:\s*\d/)
  })

  it('includes every transaction row (ref, description, debit, credit) — the complete period, not a paginated slice', async () => {
    const rows = Array.from({ length: 45 }, (_, i) => ({
      ref: `SI-${1000 + i}`,
      rawDate: '2026-07-10T00:00:00.000Z',
      desc: `Sales Invoice ${i}`,
      debit: 10 + i,
      credit: 0,
      balance: 10 + i,
    }))
    const doc = await buildStatementPdf(baseConfig({ rows, periodDebitTotal: rows.reduce((s, r) => s + r.debit, 0), periodCreditTotal: 0 }))
    const text = await extractPdfText(Promise.resolve(doc))
    // A paginated UI page would only ever show the first ~20 rows — assert
    // rows well past any such page boundary are present.
    expect(text).toContain('SI-1000')
    expect(text).toContain('SI-1044')
    expect(text).toContain('Sales Invoice 44')
  })

  it('spans multiple PDF pages once the transaction table overflows one page, and numbers them "Page X of Y"', async () => {
    const rows = Array.from({ length: 60 }, (_, i) => ({
      ref: `SI-${1000 + i}`,
      rawDate: '2026-07-10T00:00:00.000Z',
      desc: `Sales Invoice number ${i} with a longer description to use realistic row height`,
      debit: 10 + i,
      credit: 0,
      balance: 10 + i,
    }))
    const doc = await buildStatementPdf(baseConfig({ rows, periodDebitTotal: rows.reduce((s, r) => s + r.debit, 0), periodCreditTotal: 0 }))
    expect(doc.getNumberOfPages()).toBeGreaterThan(1)
    const text = await extractPdfText(Promise.resolve(doc))
    const pageCount = doc.getNumberOfPages()
    expect(text).toContain(`Page 1 of ${pageCount}`)
    expect(text).toContain(`Page ${pageCount} of ${pageCount}`)
    // The account summary (drawn once, after the last transaction row) must
    // still be present exactly once even across multiple pages.
    expect((text.match(/ACCOUNT SUMMARY/g) ?? []).length).toBe(1)
  })

  it('renders correctly for a single transaction (no pagination edge case)', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig({
      rows: [{ ref: 'SI-1', rawDate: '2026-07-10T00:00:00.000Z', desc: 'Sales Invoice', debit: 100, credit: 0, balance: 100 }],
      periodDebitTotal: 100, periodCreditTotal: 0, closingBalance: 100,
    })))
    expect(text).toContain('SI-1')
    expect(text).toContain('ACCOUNT SUMMARY')
  })

  it('shows the opening balance as a distinct labeled block, not an ordinary transaction row', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig({ openingBalance: 1234.56 })))
    expect(text).toContain('OPENING BALANCE')
    expect(text).toContain('$1,234.56')
  })

  it('shows Total Debit, Total Credit, and an emphasized Closing Balance that reconcile with the provided figures', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig()))
    expect(text).toContain('ACCOUNT SUMMARY')
    expect(text).toContain('Total Debit')
    expect(text).toContain('Total Credit')
    expect(text).toContain('CLOSING BALANCE')
    // Debit/Credit totals and the closing balance all show as plain
    // currency-formatted amounts — no trailing currency code, no DB/CR suffix.
    expect(text).toContain('$9,440.55')
    expect(text).toContain('$5,000.00')
    expect(text).toContain('$4,440.55')
  })

  it('shows the currency symbol on the per-row Debit and Credit amounts too, not just the Balance column', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig({
      rows: [{ ref: 'SI-1', rawDate: '2026-07-10T00:00:00.000Z', desc: 'Sales Invoice', debit: 321.5, credit: 0, balance: 321.5 }],
      periodDebitTotal: 321.5, periodCreditTotal: 0, closingBalance: 321.5,
    })))
    expect(text).toContain('$321.50')
  })

  it('shows a negative (in-credit) balance as a signed currency amount, with no CR accounting jargon', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig({
      rows: [{ ref: 'RV-1', rawDate: '2026-07-10T00:00:00.000Z', desc: 'Cash receipt', debit: 0, credit: 200, balance: -200 }],
      periodDebitTotal: 0, periodCreditTotal: 200, closingBalance: -200,
    })))
    expect(text).toContain('-$200.00')
    expect(text).not.toMatch(/\bCR\b/)
  })

  it('never shows DB/CR accounting-jargon terminology anywhere in the customer-facing PDF, for either sign of balance', async () => {
    const owedText = await extractPdfText(buildStatementPdf(baseConfig({
      openingBalance: 500,
      rows: [{ ref: 'SI-1', rawDate: '2026-07-10T00:00:00.000Z', desc: 'Sales Invoice', debit: 100, credit: 0, balance: 600 }],
      periodDebitTotal: 100, periodCreditTotal: 0, closingBalance: 600,
    })))
    expect(owedText).not.toMatch(/\bDB\b/)
    expect(owedText).not.toMatch(/\bCR\b/)
    // The figures themselves must be unaffected — same numbers, just without the suffix.
    expect(owedText).toContain('$500.00')
    expect(owedText).toContain('$600.00')

    const inCreditText = await extractPdfText(buildStatementPdf(baseConfig({
      openingBalance: -500,
      rows: [{ ref: 'RV-1', rawDate: '2026-07-10T00:00:00.000Z', desc: 'Cash receipt', debit: 0, credit: 100, balance: -600 }],
      periodDebitTotal: 0, periodCreditTotal: 100, closingBalance: -600,
    })))
    expect(inCreditText).not.toMatch(/\bDB\b/)
    expect(inCreditText).not.toMatch(/\bCR\b/)
    expect(inCreditText).toContain('-$500.00')
    expect(inCreditText).toContain('-$600.00')
  })

  it('never includes PID or Financial Number — explicitly excluded per product decision', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig()))
    expect(text).not.toMatch(/PID/)
    expect(text).not.toMatch(/Financial Number/i)
  })

  it('shows a "Page X of Y" footer with the client name', async () => {
    const text = await extractPdfText(buildStatementPdf(baseConfig()))
    expect(text).toContain('Page 1 of 1')
    // The dash separator is jsPDF's WinAnsi em-dash byte, which this test's
    // crude latin1 text extraction doesn't round-trip as a plain space —
    // assert the stable parts on either side instead (confirmed correct
    // visually in real PDF review).
    expect(text).toContain('Statement of Account')
    expect(text).toContain('GLOBAL CONSTRUCTION GROUP SAL')
  })
})
